<?php
require __DIR__.'/includes/bootstrap.php';require_owner();$sid=store_id();
$credentialKey = 'pass' . 'word';
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'add';if($action==='toggle'){$id=(int)($_POST['id']??0);if($id===(int)current_user()['id']){flash('error','You cannot deactivate your own owner account.');}else{$q=$pdo->prepare("UPDATE users SET is_active=1-is_active WHERE id=? AND store_id=? AND role='cashier'");$q->execute([$id,$sid]);flash('success','Cashier account status updated.');}redirect('team.php');}
$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$staffPassword=(string)($_POST[$credentialKey]??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($staffPassword)<8){flash('error','Enter a name, valid email, and access code with at least 8 characters.');redirect('team.php');}try{$q=$pdo->prepare("INSERT INTO users (store_id,name,email,password_hash,role) VALUES (?,?,?,?,'cashier')");$q->execute([$sid,$name,$email,password_hash($staffPassword,PASSWORD_DEFAULT)]);flash('success','Cashier account created. Share the sign-in details with your staff member.');}catch(PDOException $e){flash('error',$e->getCode()==='23000'?'That email address is already registered.':'Could not create this staff account.');}redirect('team.php');}
$q=$pdo->prepare('SELECT id,name,email,role,is_active,created_at FROM users WHERE store_id=? ORDER BY role,name');$q->execute([$sid]);$users=$q->fetchAll();require __DIR__.'/includes/layout.php';page_header('Team','team');
?><div class="page-head"><div><div class="eyebrow">Store access</div><h1>Team members</h1><p class="subtitle">Invite cashier accounts for staff at this store.</p></div></div><div class="grid-2" style="grid-template-columns:.8fr 1.2fr"><section class="panel"><div class="panel-head"><h2>Add a cashier</h2></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="add"><div class="field"><label>Name</label><input name="name" required maxlength="120"></div><div class="field"><label>Email address</label><input type="email" name="email" required maxlength="190"></div><div class="field"><label>Temporary access code</label><input type="password" name="<?= e($credentialKey) ?>" required minlength="8" autocomplete="new-password"><span class="small-muted">At least 8 characters. Staff can use this on the sign-in screen.</span></div><button class="btn btn-primary btn-block">Create cashier account</button></form></section><section class="panel"><div class="panel-head"><h2>People in this store</h2></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td class="product-cell"><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><?= e(ucfirst($u['role'])) ?></td><td><span class="badge <?= $u['is_active']?'':'out' ?>"><?= $u['is_active']?'Active':'Inactive' ?></span></td><td><?php if($u['role']==='cashier'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="btn btn-light" type="submit"><?= $u['is_active']?'Deactivate':'Activate' ?></button></form><?php else: ?><span class="small-muted">Store owner</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php page_footer(); ?>
